// Helper to find primary ID in a CSV row
function getRowId(row, fileName) {
  if (fileName.includes('charging_stations')) return row.unit_id;
  if (fileName.includes('process_execution_log')) return row.unit_id + '_' + row.process_id;
  if (fileName.includes('actors_reference')) return row.actor_id;
  if (fileName.includes('transport_movements')) return row.transport_id;
  if (fileName.includes('vde_test_reports')) return row.TEST_REPORT_ID || row.test_report_id;
  if (fileName.includes('maintenance_log')) return row.MAINTENANCE_ID || row.maintenance_id;
  return row.id || row.ID || row.actor_id || row.unit_id || row.process_id || row.transport_id || row.TEST_REPORT_ID || row.MAINTENANCE_ID;
}

// Pure JS string hashing function (DJB2/Murmur-like hybrid)
function getHash(str) {
  let hash = 0;
  for (let i = 0; i < str.length; i++) {
    const char = str.charCodeAt(i);
    hash = ((hash << 5) - hash) + char;
    hash = hash & hash;
  }
  return (hash >>> 0).toString(16);
}

// Parse existing ingested entities and files from Neo4j
const existingEntities = new Map();
const existingFiles = new Map();
try {
