          continue;
        }
      }

      if (ext === 'csv') {
        const rows = parseCSV(text);
        let skippedRowsCount = 0;

        rows.forEach((row, rowIdx) => {
          const rowId = getRowId(row, fileName);
          const rowText = Object.entries(row)
            .filter(([k, v]) => v !== null && v !== undefined && v !== '')
            .map(([k, v]) => `${k}: ${v}`)
            .join('\n');
          const rowHash = getHash(rowText);

          // Row-level caching check (treat missing/null hash as matching to avoid reprocessing legacy data)
          if (rowId && existingEntities.has(rowId)) {
            const storedHash = existingEntities.get(rowId);
            if (!storedHash || storedHash === rowHash) {
              skippedRowsCount++;
              return;
            }
          }

          const prompt = `You are a precise supply chain knowledge graph entity extractor. Analyze the row below from ${fileName} and extract ALL entities and relationships.\n\nDOCUMENT (${fileName} - Row ${rowIdx + 1}):\n${rowText}\n\n${entityRules}`;

          results.push({
            json: {
              fileName: fileName,
              fileType: ext,
              rowNumber: rowIdx + 1,
              prompt: prompt,
              rowHash: rowHash,
              fileHash: fileHash
            }
          });
        });
        if (skippedRowsCount > 0) {
          console.log(`Skipped ${skippedRowsCount} already ingested/unchanged rows in ${fileName}.`);
        }
      } else {
        const prompt = `You are a precise supply chain knowledge graph entity extractor. Analyze the document below and extract ALL entities and relationships.\n\nDOCUMENT (${fileName}):\n${text}\n\n${entityRules}`;

        results.push({
          json: {
            fileName: fileName,
            fileType: ext,
            prompt: prompt,
            rowHash: fileHash, // For unstructured files, the row hash is the file hash
            fileHash: fileHash
          }
        });
      }
    }
  }
}

return results;

