    const query = `MERGE (n:${label} {${idField}: '${id}'}) SET ${setParts.join(', ')} RETURN n.${idField} AS merged_id`;
    queries.push({ json: { queryType: 'entity', label, id, cypher: query } });
  }

  for (const rel of relationships) {
    const fromField = rel.from_type === 'Actor' ? 'actor_id' :
                      rel.from_type === 'Location' ? 'location_code' :
                      rel.from_type === 'ChargingStation' ? 'unit_id' :
                      rel.from_type === 'Process' ? 'process_id' :
                      rel.from_type === 'Material' ? 'material_id' : 'id';
    const toField = rel.to_type === 'Actor' ? 'actor_id' :
                    rel.to_type === 'Location' ? 'location_code' :
                    rel.to_type === 'ChargingStation' ? 'unit_id' :
                    rel.to_type === 'Process' ? 'process_id' :
                    rel.to_type === 'Material' ? 'material_id' : 'id';

    const relProps = rel.properties || {};
    const relSetParts = [];

    if (Object.keys(relProps).length > 0) {
      Object.entries(relProps)
        .filter(([k, v]) => v !== null && v !== undefined)
        .forEach(([k, v]) => {
          const safeVal = String(v).replace(/'/g, "\\'");
          relSetParts.push(`r.${k} = '${safeVal}'`);
        });
    }
    // Set source file and hash on relationship as well
    relSetParts.push(`r.ingested_at = datetime('${new Date().toISOString()}')`);
    relSetParts.push(`r.source_file = '${fileName}'`);
    if (rowHash || fileHash) {
      relSetParts.push(`r.hash = '${rowHash || fileHash}'`);
    }

    const setClause = relSetParts.length > 0 ? ' SET ' + relSetParts.join(', ') : '';

    const query = `MATCH (a:${rel.from_type} {${fromField}: '${rel.from_id}'}) MATCH (b:${rel.to_type} {${toField}: '${rel.to_id}'}) MERGE (a)-[r:${rel.relationship_type}]->(b)${setClause} RETURN type(r) AS rel_type`;
    queries.push({ json: { queryType: 'relationship', relType: rel.relationship_type, cypher: query } });
  }
}

// Append ProcessedFile metadata queries to lock in cache status
for (const [name, hash] of processedFiles.entries()) {
  const fileQuery = `MERGE (f:ProcessedFile {name: '${name}'}) SET f.hash = '${hash}', f.ingested_at = datetime() RETURN f.name AS file_cached`;
  queries.push({ json: { queryType: 'file_metadata', fileName: name, cypher: fileQuery } });
}

return queries;

parameters.cypherQuery:
CALL {
  MATCH (f:ProcessedFile)
  RETURN collect({name: f.name, hash: f.hash}) AS files
}
CALL {
  MATCH (n)
  WHERE NOT n:ProcessedFile
  RETURN collect(distinct {
    id: coalesce(
      n.actor_id, 
      n.location_code, 
      n.unit_id, 
      CASE WHEN 'Process' IN labels(n) THEN n.unit_id + '_' + n.process_id ELSE n.process_id END, 
      n.material_id, 
      n.id
    ), 
    hash: n.hash
  }) AS nodes
}
CALL {
  MATCH ()-[r:USES_TRANSPORT]->()
  RETURN collect(distinct {id: r.transport_id, hash: r.hash}) AS rels
}
RETURN 
  files AS existing_files,
  [item IN nodes + rels WHERE item.id IS NOT NULL] AS existing_entities
